<template><ThemePage><view class="delivery-page"><view class="delivery-heading"><button @tap="controller.back">返回</button><text class="delivery-title">{{ title }}</text><button :disabled="controller.loading.value||controller.busy.value" @tap="controller.load">刷新</button></view><view v-show="controller.context.value" class="delivery-card"><text class="delivery-label">本次配送身份</text><picker :range="controller.context.value?.data.contexts||[]" range-key="name" @change="controller.chooseScope"><view class="delivery-selector">{{ controller.scopeName.value }} · 选择</view></picker><text v-if="!controller.selected.value" class="delivery-muted">请选择实际配送身份；平台与门店配送分别授权。</text><text v-if="controller.context.value?.data.conflicts.length" class="delivery-warning">存在重复配送身份，请联系管理员核对。</text><slot name="identity" /></view><view v-if="controller.pending.value.length" class="delivery-warning" data-delivery="pending"><text class="delivery-label">原送达结果需核对</text><text>网络中断或页面关闭不能证明原操作未执行。先核对原操作结果。</text><view v-for="intent in controller.pending.value" :key="intent.request_key" class="delivery-stack"><text>{{ intent.body.scope_kind==='platform'?'平台配送':'门店配送' }} · 订单 {{ intent.body.order_id }}</text><text class="delivery-muted">操作编号 {{ intent.request_key }}</text><view class="delivery-controls"><button :disabled="controller.busy.value" @tap="controller.checkIntent(intent)">核对原结果</button><button v-if="controller.rejected.value.includes(intent.request_key)" @tap="controller.acknowledge(intent)">确认关闭未执行记录</button><template v-else><button :disabled="controller.busy.value||!controller.context.value||controller.context.value.scope_key!==intent.body.scope_key" @tap="controller.restoreIntent(intent)">恢复同一操作</button><button :disabled="controller.busy.value" @tap="controller.restoreIntent(intent,true)">核对并放弃</button></template></view></view></view><view v-if="controller.operationError.value" class="delivery-warning" data-delivery="result">{{ controller.operationError.value }}</view><view v-if="controller